/* --- Scene Setup --- */
/* Replaced the global "body" tag with a scoped class, and replaced "100vh" with a fixed pixel height */
.unboxing-container {
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 400px;
  background-color: #f3f4f6;
  margin: 0;
  overflow: hidden;
  width: 100%;
  border-radius: 12px;
}

.loader-scene {
  perspective: 1200px;
  position: relative;
  width: 200px;
  height: 200px;
  display: flex;
  justify-content: center;
  align-items: center;
}

/* --- The Box --- */
.box {
  width: 100px;
  height: 80px;
  position: relative;
  transform-style: preserve-3d;
  transform: rotateX(-15deg) rotateY(-25deg);
  animation: box-shake 3.5s infinite ease-in-out;
}

/* Standard Cardboard Material */
.box-face {
  position: absolute;
  background-color: #d1a578;
  border: 1px solid #b88a5d;
  box-shadow: inset 0 0 15px rgba(0, 0, 0, 0.1);
}

/* Constructing the Box Walls */
.face-back {
  width: 100px;
  height: 80px;
  transform: translateZ(-30px) rotateY(180deg);
}
.face-left {
  width: 60px;
  height: 80px;
  transform: translateX(-30px) rotateY(-90deg);
}
.face-right {
  width: 60px;
  height: 80px;
  transform: translateX(70px) rotateY(90deg);
}
.face-bottom {
  width: 100px;
  height: 60px;
  transform: translateY(50px) rotateX(-90deg);
  background-color: #a87e53;
}

/* Front is separated in HTML so the cards can sit behind it in the 3D space */
.face-front {
  width: 100px;
  height: 80px;
  transform: translateZ(30px);
}

/* The Flaps */
.box-flap {
  position: absolute;
  width: 100px;
  height: 35px;
  background-color: #d1a578;
  border: 1px solid #b88a5d;
  transform-origin: top;
}

.flap-back {
  transform: translateZ(-30px) rotateX(0deg);
  animation: flap-open-back 3.5s infinite
    cubic-bezier(0.175, 0.885, 0.32, 1.275);
}

.flap-front {
  transform: translateZ(30px) rotateX(0deg);
  animation: flap-open-front 3.5s infinite
    cubic-bezier(0.175, 0.885, 0.32, 1.275);
}

/* --- The NFC Cards --- */
.card {
  position: absolute;
  width: 48px;
  aspect-ratio: 54 / 86;
  background-color: white;
  background-position: center;
  background-size: cover;
  border-radius: 4px;
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.2);
  left: 26px;
  top: 10px;
  opacity: 0;
}

.card-1 {
  background-image: url("nfc card.png");
  animation: card-jump-left 3.5s infinite cubic-bezier(0.34, 1.56, 0.64, 1);
}
.card-2 {
  background-image: url("nfc card 2.png");
  animation: card-jump-center 3.5s infinite cubic-bezier(0.34, 1.56, 0.64, 1);
}
.card-3 {
  background-image: url("nfc card.png");
  animation: card-jump-right 3.5s infinite cubic-bezier(0.34, 1.56, 0.64, 1);
}

/* Soft shadow directly under the box for grounding */
.ground-shadow {
  position: absolute;
  width: 120px;
  height: 40px;
  background: rgba(0, 0, 0, 0.2);
  border-radius: 50%;
  top: 130px;
  filter: blur(8px);
  transform: rotateX(60deg);
}

/* =========================================
   Animation Keyframes 
   ========================================= */

@keyframes box-shake {
  0%,
  10% {
    transform: rotateX(-15deg) rotateY(-25deg) rotateZ(0deg);
  }
  12% {
    transform: rotateX(-15deg) rotateY(-25deg) rotateZ(4deg);
  }
  14% {
    transform: rotateX(-15deg) rotateY(-25deg) rotateZ(-4deg);
  }
  16% {
    transform: rotateX(-15deg) rotateY(-25deg) rotateZ(2deg);
  }
  18%,
  100% {
    transform: rotateX(-15deg) rotateY(-25deg) rotateZ(0deg);
  }
}

@keyframes flap-open-front {
  0%,
  18% {
    transform: translateZ(30px) rotateX(0deg);
  }
  22%,
  80% {
    transform: translateZ(30px) rotateX(130deg);
  }
  88%,
  100% {
    transform: translateZ(30px) rotateX(0deg);
  }
}

@keyframes flap-open-back {
  0%,
  18% {
    transform: translateZ(-30px) rotateX(0deg);
  }
  22%,
  80% {
    transform: translateZ(-30px) rotateX(-130deg);
  }
  88%,
  100% {
    transform: translateZ(-30px) rotateX(0deg);
  }
}

@keyframes card-jump-left {
  0%,
  19% {
    transform: translate3d(0, 0, -10px) rotateZ(0deg);
    opacity: 0;
  }
  20% {
    opacity: 1;
  }
  26%,
  80% {
    transform: translate3d(-35px, -90px, 15px) rotateZ(-20deg) rotateY(-10deg);
    opacity: 1;
  }
  86%,
  100% {
    transform: translate3d(0, 0, -10px) rotateZ(0deg);
    opacity: 0;
  }
}

@keyframes card-jump-center {
  0%,
  19% {
    transform: translate3d(0, 0, 0px) rotateZ(0deg);
    opacity: 0;
  }
  21% {
    opacity: 1;
  }
  28%,
  80% {
    transform: translate3d(0, -105px, 20px) rotateZ(0deg);
    opacity: 1;
  }
  86%,
  100% {
    transform: translate3d(0, 0, 0px) rotateZ(0deg);
    opacity: 0;
  }
}

@keyframes card-jump-right {
  0%,
  19% {
    transform: translate3d(0, 0, 10px) rotateZ(0deg);
    opacity: 0;
  }
  22% {
    opacity: 1;
  }
  30%,
  80% {
    transform: translate3d(35px, -90px, 25px) rotateZ(20deg) rotateY(10deg);
    opacity: 1;
  }
  86%,
  100% {
    transform: translate3d(0, 0, 10px) rotateZ(0deg);
    opacity: 0;
  }
}
